def _once(page: str, old: str, new: str, label: str) -> str:
    if page.count(old) != 1:
        raise ValueError("Nano Banana Pro template drift: " + label)
    return page.replace(old, new, 1)


def _meta(page: str, key: str, value: str) -> str:
    pattern = r'(<meta (?:name|property)="' + re.escape(key) + r'" content=")[^"]*(" />)'
    page, count = re.subn(
        pattern, lambda m: m.group(1) + escape(value, quote=True) + m.group(2),
        page, count=1,
    )
    if count != 1:
        raise ValueError("Nano Banana Pro missing metadata: " + key)
    return page


def enrich_nano_banana_pro_page(page: str) -> str:
    """Keep this a model reference while giving each major search intent an answer."""
    if 'data-nano-banana-pro-guide' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("Nano Banana Pro canonical URL drift")
    page, count = re.subn(r"<title>.*?</title>", "<title>" + escape(TITLE) + "</title>", page, count=1)
    if count != 1:
        raise ValueError("Nano Banana Pro title missing")
    for key, value in (
        ("description", DESCRIPTION),
        ("og:title", TITLE),
        ("og:description", DESCRIPTION),
        ("twitter:title", TITLE),
        ("twitter:description", DESCRIPTION),
    ):
        page = _meta(page, key, value)

    replacements = [
        (
            "<h1>Nano Banana Pro<br><span>verified model reference.</span></h1>",
            "<h1>Nano Banana Pro<br><span>Gemini 3 Pro Image · API, 4K &amp; pricing.</span></h1>",
        ),
        (
            "<p>Google premium image generation and editing model for complex graphics, high-fidelity product mockups, brand consistency and precise text rendering.</p>",
            "<p>" + escape(HERO) + "</p>",
        ),
        (
            '<div><strong>65,536</strong><span>context tokens</span></div>',
            '<div><strong>1K–4K</strong><span>generated image sizes</span></div>',
        ),
        (
            '<div><strong>32,768</strong><span>max output</span></div>',
            '<div><strong>$0.134</strong><span>1K/2K image output estimate</span></div>',
        ),
        (
            '<div><span>STANDARD INPUT</span><strong>$2.00</strong><small>per 1 million tokens (IMAGE output; text output billed separately)</small></div>',
            '<div><span>TEXT / IMAGE INPUT</span><strong>$2.00</strong><small>per million input tokens (Standard API)</small></div>',
        ),
        (
            '<div><span>STANDARD OUTPUT</span><strong>$120.00</strong><small>per 1 million tokens (IMAGE output; text output billed separately)</small></div>',
            '<div><span>GENERATED IMAGE OUTPUT</span><strong>$120.00</strong><small>per million image tokens; text/thinking billed separately</small></div>',
        ),
        (
            '<article><span>REASONING</span><h3>supported</h3><p>Only provider-documented reasoning controls are shown; missing controls remain unpublished rather than inferred.</p></article>',
            '<article><span>THINKING</span><h3>Supported</h3><p>Google documents intermediate reasoning for advanced image tasks; individual thinking-level controls are not inferred.</p></article>',
        ),
        (
            '<p>SXF preserves the provider-published native billing basis. Only calculator-eligible generative token models enter token-cost arithmetic; specialist units and input-only embeddings remain visible without forced conversion.</p>',
            '<p>The $120 output rate is for generated IMAGE tokens; text/thinking output costs $12 per million tokens. Final requests also bill input usage and may include Google Search grounding. See the 1K–4K and Batch pricing examples below.</p>',
        ),
    ]
    for i, (old, new) in enumerate(replacements):
        page = _once(page, old, new, str(i))

    match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if match is None:
        raise ValueError("Nano Banana Pro missing JSON-LD graph")
    schema = json.loads(match.group(2))
    graph = schema.get("@graph", [])
    article = next((node for node in graph if node.get("@type") == "TechArticle"), None)
    if article is None or not any(node.get("@type") == "BreadcrumbList" for node in graph):
        raise ValueError("Nano Banana Pro schema contract changed")
    article.update({
        "headline": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "citation": SOURCES,
        "mainEntityOfPage": {"@id": CANONICAL},
        "author": {"@type": "Organization", "name": "SXF / AI", "url": "https://sxf.si/"},
        "publisher": {"@type": "Organization", "name": "SXF / AI", "url": "https://sxf.si/"},
        "about": {
            "@type": "Thing",
            "name": "Nano Banana Pro",
            "alternateName": "Gemini 3 Pro Image",
            "identifier": "gemini-3-pro-image",
            "sameAs": SOURCES[0],
        },
        "keywords": [
            "Nano Banana Pro", "Gemini 3 Pro Image",
            "Nano Banana Pro API", "Nano Banana Pro pricing",
            "Gemini 3 Pro Image 4K", "Nano Banana Pro image editing",
        ],
    })
    graph.insert(0, {
        "@type": "WebPage",
        "@id": CANONICAL,
        "url": CANONICAL,
        "name": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "inLanguage": "en",
        "mainEntity": {"@id": CANONICAL + "#article"},
        "breadcrumb": {"@id": CANONICAL + "#breadcrumb"},
    })
    breadcrumb = next(node for node in graph if node.get("@type") == "BreadcrumbList")
    breadcrumb["@id"] = CANONICAL + "#breadcrumb"
    graph.append({
        "@type": "FAQPage",
        "@id": CANONICAL + "#faq",
        "url": CANONICAL + "#nbp-faq",
        "inLanguage": "en",
        "mainEntity": [
            {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}}
            for q, a in FAQS
        ],
    })
    jsonld = json.dumps(schema, ensure_ascii=False, separators=(",", ":"))
    page = page[:match.start(2)] + jsonld + page[match.end(2):]
    return _once(page, _MARKER, SECTIONS + FAQ_HTML + "\n\n        " + _MARKER, "insertion point")
